function toFood(row: Row): Food {
  const [id, name, emoji, category] = row;
  const food: Food = {
    id, name, emoji, category: CATEGORIES[category],
    kcal: row[4],
    protein: row[5],
    fat: row[6],
    carbs: row[7],
    fiber: row[8],
    salt: row[9],
    sodium: row[10],
    potassium: row[11],
    calcium: row[12],
    magnesium: row[13],
    phosphorus: row[14],
    iron: row[15],
    zinc: row[16],
    copper: row[17],
    manganese: row[18],
    vitaminA: row[19],
    vitaminD: row[20],
    vitaminE: row[21],
    vitaminK: row[22],
    vitaminB1: row[23],
    vitaminB2: row[24],
    vitaminB6: row[25],
    vitaminB12: row[26],
    folate: row[27],
    pantothenic: row[28],
    biotin: row[29],
    vitaminC: row[30],
    officialName: row[31] === 0 ? name : row[31] as string,
    common: row[33] === 1,
  };
  const estimated = row[32] as number;
  if (estimated >= 0) food.estimated = ESTIMATED[estimated];
  return food;
}

export const FOODS: readonly Food[] = ROWS.map(toFood);
